	parser.add_argument('--freeze',type=Path);args=parser.parse_args();freeze_path=args.freeze.resolve() if args.freeze is not None else ROOT/'docs/declaration-interop-16-api-a-freeze-3.json';freeze=json.loads(freeze_path.read_text());freeze_matches=all(sha(ROOT/name)==record['sha256'] for name,record in freeze['source_inventory'].items());assert args.freeze is None or freeze_matches;compiler=args.compiler.resolve();freeze_matches=freeze_matches and sha(compiler) in [freeze['primary_compiler']['sha256'],freeze['strict_compiler']['sha256']];assert args.freeze is None or freeze_matches;output=args.output.resolve();assert not output.is_relative_to(ROOT);output.mkdir(parents=True,exist_ok=True);work=Path(tempfile.mkdtemp(prefix='byte-api-b3-windows-',dir=output));media=work/'media';media.mkdir();here=Path(__file__).resolve().parent;sources=[Path(__file__).resolve(),*[here/('api-b3'+suffix) for suffix in ['-leaf.astra','-component.astra','-protocol.astra','-com-import.astra','-com-client.cpp','-client.c','-support.c']],ROOT/'lib/runtime/interop/foreign-14.c'];receipt=dict(scope='API B3 common source current C+COM regression; explicit --freeze required for challenge credit; native Windows execution required',freeze_enforced=args.freeze is not None,freeze_matches=freeze_matches,freeze_sha256=sha(freeze_path),compiler_sha256=sha(compiler),sources={str(p.relative_to(ROOT)):sha(p) for p in sources},checks=[],products={},execution_expectations={})
